package com.healthcare.entity;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="medical_records",indexes=@Index(columnList="patient_id,created_at")) public class MedicalRecord {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(optional=false) private Patient patient;@ManyToOne(optional=false) private Doctor doctor;@Column(nullable=false,length=4000) private String diagnosis;@Column(length=4000) private String allergies;@Column(length=4000) private String notes;@Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now();protected MedicalRecord(){}public MedicalRecord(Patient p,Doctor d,String diagnosis,String allergies,String notes){patient=p;doctor=d;this.diagnosis=diagnosis;this.allergies=allergies;this.notes=notes;}public Long getId(){return id;}public Patient getPatient(){return patient;}public Doctor getDoctor(){return doctor;}public String getDiagnosis(){return diagnosis;}public String getAllergies(){return allergies;}public String getNotes(){return notes;}public Instant getCreatedAt(){return createdAt;}}
